const qnet='https://www.q-net.or.kr/';
const work24='https://www.work24.go.kr/cm/c/f/1100/selecSystInfo.do?currentPageNo=1&recordCountPerPage=12&systClId=SC00000004&systId=SI00000351';
const source=(url,label)=>`<p class="editorial-note">확인 근거 <a href="${url.replaceAll('&','&amp;')}" target="_blank" rel="noopener">${label}</a> · 2026년 11월 6일 해당 안내 확인. 본문의 기록표·문의 예시는 편집자의 준비 제안이며 공식 제출 서식이 아닙니다.</p>`;
const table=(caption,heads,rows)=>`<div class="verified-table" tabindex="0" role="region" aria-label="${caption}"><table><caption>${caption}</caption><thead><tr>${heads.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
module.exports=[
 {slug:'전기산업기사-응시자격-경력증명서',
  html:`<h2>응시자격 확인은 자가진단과 서류심사를 나눠 진행하세요</h2><p>전기산업기사 응시자격이 궁금하다면 보유 자격, 관련 학력, 회사별 실제 담당 업무를 먼저 정리합니다. Q-Net의 응시자격 자가진단은 준비 방향을 보는 절차이고, 최종 인정은 제출 자료 심사로 확인해야 합니다. 회사 이름에 ‘전기’가 있거나 시설관리 직함을 썼다는 이유만으로 인정된다고 단정할 수 없습니다.</p><p>예를 들어 시설관리 업무를 했다면 회사에 증명서를 요청할 때 ‘시설관리 담당’만 적기보다 실제 수행한 전기 설비 점검·보수 업무와 근무기간이 확인되도록 요청하세요. 이는 작성 방향의 예시이지, 그 문구만 넣으면 경력이 인정된다는 뜻이 아닙니다. 하지 않은 업무를 추가하거나 기간을 늘려 적으면 안 됩니다.</p>${table('경력증명서 요청 전에 남길 메모',['확인할 자료','내가 적을 내용','확인 결과'],[['취득 자격','종목·급수·취득일','내가 선택할 응시 경로 확인'],['회사별 경력','시작·종료일과 실제 업무','겹친 기간·업무 미기재 확인'],['서류 제출','응시 회차·제출 기한·접수 방식','제출 완료와 심사 결과 각각 기록']])}${source(qnet+'rcv001.do?gSite=Q&id=rcv00104','Q-Net 응시자격 서류 제출 안내')}`,
  faq:['전기산업기사 응시자격 확인은 어디서 하나요?','Q-Net의 마이페이지에서 응시자격 자가진단으로 경로를 살피고, 응시자격서류 제출확인에서 본인 제출·심사 상태를 확인합니다. 자가진단 결과를 최종 승인이나 경력 인정서로 사용하지 마세요.']},
 {slug:'큐넷-시험취소-환불-기준',title:'큐넷 시험 취소 환불 기간과 환불 불가 메시지 확인',description:'큐넷 국가기술자격 취소 시 100%·50% 환불 기간과 회차 시행 초일을 확인하고 환불 가능한 기간이 아니라는 메시지가 나올 때 점검할 순서입니다.',
  html:`<h2>환불이 가능한 기간이 아니라는 메시지가 나오면</h2><p>‘환불이 가능한 기간이 아닙니다’라는 문구만으로 결제 오류라고 판단하지 마세요. 국가기술자격 일반 기준은 개인 시험일이 아니라 해당 회차의 시험 시작일을 사용합니다. 접수 내역의 종목·회차·정기/상시·빈자리 접수 여부부터 대조합니다. 공인중개사 같은 국가전문자격에는 이 글의 비율을 그대로 적용하지 않습니다.</p><ol><li>접수 내역에서 취소하려는 원서가 맞는지 확인합니다. 필기와 실기, 다른 회차 원서를 혼동하지 않습니다.</li><li>회차 공고의 시행 초일과 현재 취소 가능 기간을 확인합니다. 상시 필기나 빈자리 추가접수에는 일반 설명과 다른 안내가 있을 수 있습니다.</li><li>기간 안이라고 보이는데 진행되지 않으면 오류 문구·발생 시각·결제수단을 적고 공식 고객지원에 문의합니다. 개인정보가 담긴 화면은 공개 게시판에 올리지 않습니다.</li></ol><p>일반 취소 기간이 끝난 경우와 취소는 완료됐지만 돈이 아직 들어오지 않은 경우는 다릅니다. 후자는 취소 완료 내역과 카드 승인취소 또는 환불 계좌를 확인하세요. 질병 등 사후환불은 별도 요건·증빙 심사에 따른 절차이며 메시지가 뜬다는 이유만으로 적용되지는 않습니다.</p>${source(qnet+'crf022.do?gSite=Q&id=crf02201','Q-Net 기술자격 환불 안내')}`,
  faq:['공인중개사 취소도 같은 환불 기간인가요?','아닙니다. 이 글은 국가기술자격 일반 안내입니다. 공인중개사 등 국가전문자격은 해당 종목 홈페이지의 회차 공고와 전문자격 환불 안내를 확인해야 합니다.']},
 {slug:'내일배움카드-훈련장려금-지급조건',
  html:`<h2>훈련비 입금과 내 통장으로 받는 장려금은 다릅니다</h2><p>내일배움카드의 훈련비 지원 한도는 자유롭게 출금하는 현금이 아닙니다. 수강료 지원과 훈련장려금은 구분합니다. 고용24 일반 안내는 장려금을 조건에 따라 본인이 등록한 계좌로 지급한다고 설명합니다. 카드 발급이 됐거나 수업에 출석했다는 사실만으로 이번 달 입금액이 확정되는 것은 아닙니다.</p>${table('입금 내역을 찾기 전에 구분할 항목',['헷갈리는 항목','먼저 확인할 것','문의할 내용'],[['훈련비 지원','수강료와 자비부담금 내역','카드 결제 금액·지원 범위'],['훈련장려금','해당 과정·단위기간·출결 확정 여부','대상 여부·인정 출석일·등록 계좌'],['다른 참여수당','지급 기관과 사업명','중복 제한·각 사업의 지급 기준']])}<p>입금자명에 ‘훈련비’나 ‘고용부’가 보이더라도 이름만으로 지급 항목을 확정하지 마세요. 본인 과정과 단위기간을 정리해 훈련기관에 어떤 항목이 처리됐는지 묻습니다. ‘11월에 입금됐으니 11월 출석분’이라고 추정하기보다 어느 기간분인지 확인하는 편이 정확합니다. 전국 공통 입금일을 임의로 정해 안내하지 않습니다.</p>${source(work24,'고용24 국민내일배움카드 훈련비·장려금 안내')}`,
  faq:['내일배움카드 지원금은 카드 계좌에 현금으로 들어오나요?','훈련비 지원 한도와 현금으로 지급되는 훈련장려금은 다른 항목입니다. 장려금은 지급 대상·출석 등 조건을 충족하는지와 본인이 등록한 계좌를 확인하세요. 카드 한도를 통장에서 출금하는 방식으로 생각하면 안 됩니다.']},
 {slug:'큐넷-필기면제기간-실기-재응시',title:'큐넷 필기 유효기간 확인과 실기 재응시 준비',description:'큐넷 필기 유효기간은 본인 계정의 면제정보에서 확인하세요. 합격 발표일과 시험일을 구분하고 면제 종료 전 실기 접수·시행 일정을 대조하는 방법입니다.',
  html:`<h2>필기 유효기간은 면제정보에서 본인 날짜를 확인합니다</h2><p>검색에서 말하는 ‘필기 유효기간’을 확인하려면 Q-Net의 필기시험 면제기간 안내와 본인 계정의 면제정보를 봅니다. 국가기술자격 필기 합격에 따른 면제는 합격자 발표일부터 2년이라는 일반 안내를 출발점으로 삼되, 시험을 치른 날짜에 단순히 2년을 더해 종료일을 확정하지 마세요.</p><ol><li>Q-Net에 본인 계정으로 로그인하고 마이페이지의 면제정보보기에서 시험면제를 확인합니다.</li><li>종목명·합격 정보·면제기간을 함께 적습니다. 다른 종목이나 국가전문자격의 면제와 섞지 않습니다.</li><li>응시하려는 실기 회차의 접수 기간과 시행 기간을 대조합니다. 만료일과 접수·시험일이 걸쳐 있으면 해당 회차 적용 여부를 공단에 확인합니다.</li></ol><p>문의할 때는 ‘기간이 남았나요?’보다 ‘조회된 면제 종료일은 ○월 ○일이고, 응시하려는 실기는 ○회입니다. 이 회차에 면제가 적용되는지 확인하고 싶습니다’라고 종목과 회차를 함께 전달하면 확인할 대상을 좁힐 수 있습니다. 접수 화면에서 실제 적용 여부를 확인한 기록도 보관하세요.</p>${source(qnet+'myp007.do?id=myp00702&gSite=Q','Q-Net 필기시험 면제기간 조회·로그인 필요')}`,
  faq:['필기 유효기간이 조회되지 않으면 다시 필기를 봐야 하나요?','조회되지 않는다는 사실만으로 만료라고 단정하지 마세요. 로그인 계정, 종목명과 합격 기록을 대조하고 공식 고객지원에 확인한 뒤 재접수 여부를 판단합니다.']},
 {slug:'국민연금-추납-신청-비용-확인',title:'국민연금 추납 가능 기간 조회와 금액 확인 방법',description:'국민연금 가입내역의 공백과 실제 추납 가능한 기간은 다릅니다. 전자민원 확인 순서와 상담 메모로 대상 개월수·고지 예상액·분할 이자를 구분해 확인하세요.',
  html:`<h2>추납 가능 기간 조회는 가입내역의 공백 확인부터 시작합니다</h2><p>국민연금공단 홈페이지에서 본인 인증 후 가입내역을 확인하고, 전자민원의 ‘추납보험료 납부 신청’ 안내를 찾습니다. 개인 가입 상태에 따라 온라인에서 확인할 수 있는 범위가 다를 수 있으므로, 신청서를 제출하기 전 대상 기간과 예상 금액을 확인하려는 것인지 구분하세요. 단순히 가입 기록이 비어 있다는 이유로 그 기간 전체가 추납 대상으로 확정되지는 않습니다.</p>${table('공단 상담에 가져갈 추납 조회 메모',['적어갈 정보','상담에서 받을 답'],[['현재 가입 상태와 조회 날짜','지금 추납 신청이 가능한 상태인지'],['공백 시작월·종료월·당시 사유','실제 대상 기간과 제외 기간'],['선택하려는 개월수','납부 예상 원금과 적용 산정 기준'],['일시납·분할납 희망','납부 일정·총이자·기간 반영 시점']])}<p>예를 들어 본인이 기억하는 공백은 30개월인데 공단이 확인한 대상은 18개월이라면, 비용을 비교할 출발점은 30개월이 아니라 확인된 18개월입니다. 이 숫자는 상담 과정을 설명하는 가정으로 실제 인정 사례가 아닙니다. 선택 기간별 금액과 예상 연금은 공단에서 따로 확인하고, 월 납부액이 낮다는 이유만으로 분할 총비용도 같다고 생각하지 마세요.</p>${source('https://www.nps.or.kr/elctcvlcpt/comm/getOHAC0000M3.do?menuId=MN24000938','국민연금공단 개인 전자민원·추납보험료 납부 신청')}`,
  faq:['국민연금 추납 금액은 조회한 즉시 납부해야 하나요?','조회·상담, 실제 신청, 고지와 납부는 구분해야 합니다. 예상액을 확인하려는 단계인지 신청을 제출한 단계인지 살피고, 확정된 고지액·기한·이자 조건을 공단에서 확인하세요. 추납은 의무 납부를 강제하는 제도가 아닙니다.']},
 {slug:'사진기능사-실기-촬영-출력-연습',
  html:`<h2>한 장을 출력까지 마친 뒤 막힌 구간을 기록하세요</h2><p>사진기능사 실기를 처음 준비한다면 잘 나온 사진 수보다 촬영 원본을 옮기고 결과물을 출력하기까지 스스로 끝낸 횟수를 기록해 보세요. 아래는 편집자가 제안하는 연습일지입니다. 시험 과제나 공식 배점표를 재현한 것이 아니며, 구체적인 촬영·파일·출력 조건은 응시연도의 공식 자료를 따릅니다.</p>${table('촬영부터 출력까지 연습 기록 예시',['단계','내가 남길 기록','다음 연습의 목표'],[['촬영','선택한 설정과 의도·원본 위치','결과가 달라진 원인을 한 가지씩 비교'],['파일 이동','카메라에서 PC까지 저장한 경로','원본과 수정본을 혼동하지 않기'],['후보정','무엇을 왜 바꿨는지','같은 원본으로 처리 전후 대조'],['출력','설정과 실제 출력물 차이','화면 확인만으로 종료하지 않기']])}<p>수업 상담에서는 ‘실기 대비반인가요?’에서 한 걸음 더 나아가 ‘제가 직접 촬영한 파일을 제가 옮기고 출력까지 해보나요? 출력 실패 때 재연습 비용은 어떻게 되나요?’를 물어보세요. 특정 카메라 구매나 학원 등록을 권하는 목록이 아니라, 이미 가진 장비·대여 환경으로 부족한 구간을 확인하기 위한 질문입니다.</p>`,
  faq:['사진기능사 실기 학원은 촬영 시간만 비교하면 되나요?','촬영뿐 아니라 PC 저장·후보정·출력까지 본인이 처리할 기회와 실패 후 재연습 조건을 비교하세요. 위 연습표의 단계별로 혼자 못 끝낸 구간을 표시하면 필요한 수업 범위를 좁힐 수 있습니다.']},
 {slug:'큐넷-자격취득확인서-취업제출',title:'큐넷 자격증 취득확인서 발급과 취업 서류 제출 방법',description:'큐넷에서 자격취득사항확인서를 발급하는 순서와 발급내역·출력 확인 방법입니다. 자격증 사본과 확인서를 구분하고 채용처가 허용하는 증빙인지 확인하세요.',
  html:`<h2>자격증 취득확인서는 공식 문서명을 확인해 발급합니다</h2><p>‘자격증 취득확인서’로 찾고 있다면 Q-Net의 자격취득사항확인서와 채용공고가 요구한 문서명을 대조하세요. 자격증 사본, 상장형 자격증, 자격취득사항확인서는 발급 형태가 다릅니다. 확인서를 발급할 수 있다는 사실과 그 회사가 해당 문서를 받는다는 사실은 구분해야 합니다.</p><ol><li>Q-Net의 ‘자격증·확인서 → 확인서발급 → 확인서발급 안내’를 엽니다.</li><li>본인 계정 로그인 후 확인서발급 신청에서 요구에 맞는 문서와 취득 종목을 확인합니다.</li><li>확인서발급 내역에서 발급한 문서를 조회하고 인쇄·출력 결과를 확인합니다.</li><li>이름·종목·급수·취득 정보와 채용공고의 증빙 요건을 대조한 뒤 지정된 경로로 제출합니다.</li></ol><p>제출처에 물을 때는 ‘자격증이 있는데요’보다 ‘공고의 자격증 사본 대신 Q-Net 발급 자격취득사항확인서를 제출해도 되나요? 필요한 종목과 발급일 제한이 있나요?’처럼 문서명을 명시하세요. 출력 오류가 있으면 임의로 내용을 재작성하지 말고 공식 도움말의 브라우저·뷰어 안내부터 확인합니다.</p>${source(qnet+'iss001.do?gSite=Q&id=iss00101','Q-Net 확인서 발급 신청·내역·진위 확인 안내')}`,
  faq:['자격증 취득사실확인서라는 검색어로 찾아도 같은 문서인가요?','검색할 때 쓰는 표현과 실제 발급 문서명은 다를 수 있습니다. Q-Net에서 발급할 문서의 명칭·포함 내용을 확인하고 제출처가 그 서류를 허용하는지 확인하세요. 검색어가 비슷하다는 이유로 다른 확인서를 대신 제출하지 않습니다.']},
 {slug:'과정평가형-검정형-자격증-차이',
  html:`<h2>차이를 알았다면 내 시간표로 두 경로를 비교하세요</h2><p>과정평가형과 검정형의 차이는 ‘어느 쪽이 무조건 쉽다’가 아니라 자격 취득까지 필요한 참여·준비 경로입니다. 과정평가형은 지정 교육·훈련과정 이수와 내부·외부평가를 거칩니다. 일반 필기·실기 대비반을 다녔다고 과정평가형 참여가 되는 것은 아닙니다.</p>${table('가상 상황으로 비교하는 준비 경로',['내 상황','검정형에서 확인할 것','과정평가형에서 확인할 것'],[['현재 주간 근무 중','해당 종목 응시자격·시험일과 개인 연습시간','지정 과정의 요일·시간과 실제 출석 가능 여부'],['처음 배우며 실습 필요','개별 수업의 실습 범위·시험 대비 범위','모집 과정의 지정 여부·종목·훈련 내용'],['빨리 취업해야 함','접수·실기·발표까지의 일정','훈련 종료와 외부평가 일정·취업 준비 병행']])}<p>가령 평일 낮에 일하는 사람에게 과정의 총시간이 충분하다는 장점만 설명해도, 실제 출석이 어렵다면 선택할 수 없습니다. 반대로 혼자 실습할 환경이 없다면 시험 일정만 빠른 경로도 부담이 될 수 있습니다. 합격률이나 수강료 한 숫자로 결론 내리지 말고 본인 일정과 실습 여건을 함께 적으세요.</p>${source('https://c.q-net.or.kr/cbq/introduce/examMethInfoList.do','CQ-Net 과정평가형 종목별 평가 방법')}`,
  faq:['과정평가형 학원인지 어떻게 확인하나요?','광고의 문구만 보지 말고 CQ-Net에서 지정 교육·훈련과정과 해당 종목·운영기관을 확인하세요. 같은 기관이라도 일반 시험 대비반과 지정 과정은 구분해야 합니다.']},
 {slug:'폐업한-회사-경력증명서-대체서류',
  html:`<h2>대체서류를 모으기 전에 제출 목적부터 문의하세요</h2><p>폐업한 회사 경력증명서 대체서류는 채용 제출인지 자격시험 응시자격 심사인지에 따라 확인 기준이 달라집니다. 건강보험 자격득실확인서 한 장으로 모든 제출처의 담당 업무 증명이 끝난다고 단정하지 마세요. 먼저 무엇을 증명해야 하는지 받은 뒤 그 항목을 뒷받침할 자료를 묶습니다.</p><p>아래는 제출처에 보낼 수 있는 문의 문장 예시입니다. 개인정보가 들어간 증빙을 먼저 전부 보내지 말고 필요한 서류 종류부터 확인하세요.</p><blockquote><p>이전 근무처가 폐업해 신규 경력증명서 발급이 어렵습니다. 귀 기관의 경력 심사에서 근무기간과 담당 직무를 각각 어떤 서류로 확인하는지 안내 부탁드립니다. 제가 보유한 자료는 보험 가입 이력, 급여 관련 자료, 당시 근로계약서입니다. 정해진 대체서식과 추가 확인 절차가 있다면 함께 알려주세요.</p></blockquote><p>담당자 답변에는 문의 날짜와 제출 목적을 적어 보관합니다. ‘채용처 A에서 받았다’는 경험을 ‘자격시험 B에서도 받는다’로 넓혀 쓰지 않습니다. 원본이 없는 업무 기록을 새로 만들어 증빙처럼 제출하거나 동료의 개인정보를 동의 없이 함께 보내는 방식은 피하세요.</p>`,
  faq:['폐업한 회사의 보험 가입 기록만 있으면 경력 인정이 되나요?','보험 이력은 사업장과 기간 확인에 도움이 되지만 실제 담당 업무까지 모두 입증하지는 못합니다. 채용처 또는 시험 시행기관에 목적별 대체서류와 심사 절차를 확인해야 합니다.']},
 {slug:'농업기계정비기능사-실기-정비-학원',
  html:`<h2>농기계정비 실기 학원 검색 후 세 가지를 확인하세요</h2><p>‘농기계정비기능사 학원’으로 검색했더라도 상담하는 과정이 현재 응시할 농업기계정비기능사의 준비 과정인지 확인합니다. 운전 과정이나 장비 시연 강의를 정비 실기 대비 과정과 혼동하지 마세요. 이 글은 현재 모집 중인 학원 목록이나 지역별 추천 순위를 제공하지 않습니다.</p>${table('학원 상담 때 채워 넣을 비교표',['질문','기관 A','기관 B'],[['응시연도 출제기준과 공개문제를 어느 자료로 준비하나요?','확인한 자료명·적용기간 기록','확인한 자료명·적용기간 기록'],['수강생이 직접 점검·작업할 장비와 시간은 어떻게 되나요?','장비·정원·개인 실습시간 기록','장비·정원·개인 실습시간 기록'],['보충 연습·소모품·장비 사용에 추가 비용이 있나요?','포함 범위·추가 비용 기록','포함 범위·추가 비용 기록']])}<p>국비 과정을 찾는 경우 고용24 훈련 검색에서 종목명·지역·기간을 좁히고, 검색 결과의 과정명이 정비와 운전 중 무엇인지 먼저 읽으세요. 검색에 나왔다는 이유만으로 수강 가능·무료·현재 모집 중이라고 판단하지 않습니다. 지원 유형별 자비부담액과 실제 개인 실습시간은 따로 확인해야 합니다.</p>${source('https://www.work24.go.kr/cm/main.do','고용24 훈련 찾기·신청')}`,
  faq:['근처 농기계정비 실기 학원이 없으면 온라인 강의만 들어도 되나요?','이론 학습과 실제 장비 점검·작업은 다릅니다. 이동 가능한 지역과 기간을 넓혀 실습 환경을 확인하고, 비용에는 교통·숙박·추가 연습도 포함하세요. 온라인 수강만으로 실기 준비가 충분하다고 보장할 수 없습니다.']},
 {slug:'스마트폰-취업서류-PDF-제출',
  html:`<h2>PDF 첨부가 안 될 때는 오류를 나눠 확인합니다</h2>${table('취업 서류 업로드 오류 점검',['증상','먼저 할 일','피할 일'],[['파일 선택 창에서 서류가 안 보임','스캔 앱에서 PDF 저장 여부와 실제 저장 위치 확인','사진 확장자만 .pdf로 바꾸기'],['용량 초과 안내','공고의 파일별 한도를 확인하고 원본 보관 후 제출본 조정','숫자·도장이 안 읽힐 때까지 반복 압축'],['파일은 붙었지만 열리지 않음','첨부본을 다시 열어 페이지 수·암호·읽힘 확인','원본 확인 없이 같은 파일 재전송'],['첨부 후에도 지원 완료가 안 됨','필수항목과 별도 제출 버튼·접수번호 확인','파일 업로드를 지원서 최종 제출로 생각하기']])}<p>가상 예를 들어 경력증빙 3장이 한 PDF에 들어가야 하는 공고라면, 제출 전 휴대폰에서 파일을 열어 1·2·3쪽 순서와 하단 발급 정보가 보이는지 확인합니다. 공고가 서류별 개별 첨부를 요구한다면 한 파일로 합치는 방식이 맞지 않을 수 있습니다. 제출처의 형식·용량 규칙을 임의의 권장값보다 우선하세요.</p><p>채용 서류에는 민감한 정보가 있으므로 오류 해결을 위해 파일 전체를 공개하거나 모르는 사람에게 대신 변환해 달라고 보내지 마세요. 파일명에는 주민등록번호를 넣지 않고, 문의할 때는 개인정보 없는 오류 문구와 사용 기기·앱부터 전달합니다.</p>${source('https://support.google.com/drive/answer/3145835?hl=ko','Google Drive 공식 문서 스캔·PDF 저장 도움말')}`,
  faq:['스마트폰에서 제출한 PDF가 제대로 첨부됐는지 어떻게 확인하나요?','지원 시스템의 미리보기나 첨부파일 내려받기로 실제 제출본을 열어봅니다. 페이지 수·순서·읽힘을 확인하고, 별도 최종 제출을 마친 뒤 완료 화면이나 접수번호까지 보관하세요.']},
 {slug:'조리기능사-50대-취업-가능할까',
  html:`<h2>초보 지원자는 공고 두 개를 같은 항목으로 적어보세요</h2><p>아래 양식은 위의 과거 공고를 현재 채용정보로 바꾸는 표가 아닙니다. 지금 지원하려는 공고를 독자가 직접 비교할 때 쓸 수 있도록 만든 기록표입니다. 이전 표본의 월급이나 경력 조건을 새 공고에 그대로 옮겨 적지 마세요.</p>${table('조리 초보 지원 전 비교 메모',['항목','지원할 공고에서 기록할 내용','내가 확인할 질문'],[['업무','조리·전처리·배식·세척의 범위','신입이 처음 맡는 작업은 무엇인가요?'],['시간','출근시각·요일·휴게 표기','첫 출근 시각에 이동할 수 있나요?'],['자격·경력','필수·우대·관계없음 구분','경력 없는 지원자의 교육이 있나요?'],['임금','시급·월급·별도 수당 표기','계약상 시간과 실제 업무표는 어떻게 되나요?']])}<p>자격증 공부를 시작할지는 이 표를 채운 뒤 결정해도 늦지 않습니다. 예를 들어 통근이 불가능한 새벽 근무라면 시험 합격만으로 그 공고에 지원할 수 있는 조건이 완성되지 않습니다. 자격 필수 공고를 목표로 한다면 자격·면허 조건을 따로 확인하고, 경력 우대 문구는 경력 필수와 구분해 읽습니다. 취업 가능성이나 신입 급여를 보장하는 표가 아닙니다.</p><p><a href="/재취업-직무-비교/">시설관리·돌봄·조리·물류 조건 비교표</a>에서 현재 생활과 맞는 근무조건을 먼저 정리할 수도 있습니다.</p>`,
  faq:['50대 조리 초보는 학원 등록 전에 무엇부터 해야 하나요?','지금 지원 가능한 생활권 공고에서 출근시각·업무·경력·자격 조건을 먼저 기록하세요. 자격시험 대비가 필요한지, 신입 현장 적응 교육을 먼저 확인해야 하는지 구분하면 교육비를 비교할 기준이 생깁니다.']},
 {slug:'지게차운전기능사-국비지원-신청방법',
  html:`<h2>국비지원 신청은 채용조건 확인 뒤 과정별로 진행합니다</h2><p>지게차운전기능사 국비 과정을 찾는다면 목표 공고의 장비·자격·면허 조건을 먼저 적고 고용24의 훈련 검색으로 넘어갑니다. 이 글 위쪽의 채용 표본은 과거 비교자료이며 현재 모집이나 무료 수강을 보장하지 않습니다.</p><ol><li>고용24에서 국민내일배움카드 발급 대상과 현재 카드 상태를 확인합니다. 실업상태에서 신청하는 경우 공식 안내의 구직신청 절차도 확인하세요.</li><li>훈련 찾기에서 지게차운전기능사 과정의 지역·훈련 기간을 좁힙니다. 자격시험 대비와 별도 교육 과정의 범위를 구분합니다.</li><li>해당 과정 상세에서 훈련비·본인부담액·일정·기관을 확인합니다. 카드 발급과 과정 수강 신청은 같은 단계가 아닙니다.</li><li>기관에 실제 개인 운전 연습시간, 정원·장비 수, 시험료·추가 연습비 포함 여부를 문의한 뒤 과정 신청 안내를 따릅니다.</li></ol>${table('결제 전 적어둘 세 가지 숫자',['항목','적어둘 값'],[['교육비','본인부담액 + 별도 시험·연습 비용'],['시간','통학시간 + 수업일정 + 개인 실습 기회'],['지원 가능일','수료·시험·별도 면허 확인 이후 실제 취업 준비 일정']])}<p>학원의 ‘국비 가능’ 문구는 본인에게 해당 수업이 전액 무료라는 뜻으로 해석하지 마세요. 지원자 상태와 과정에 따른 부담액을 확인합니다. 취업 공고가 요구하는 면허 범위는 훈련 수료와 별도 문제이므로 신청 전에 준비 범위를 서면 안내로 받아두는 편이 좋습니다.</p>${source(work24,'고용24 국민내일배움카드 지원·신청 절차')}`,
  faq:['내일배움카드만 발급되면 지게차 학원 등록이 끝나나요?','아닙니다. 카드 발급과 훈련과정 수강 신청은 별도 단계입니다. 과정별 기간·본인부담액·모집 상태와 훈련기관 안내를 확인하고 실제 신청·선발 또는 등록 절차를 마쳤는지 확인해야 합니다.']}
];
